import React, {useState} from 'react';
import './Pagination.scss';
import TextField from "../textField/TextField";
import { MpaIcon } from "../icon/MpaIcon";

export interface PaginationProps {
  /**
   * Identifying value for the pagination.
   */
  id: string;
  /**
   * Determines the current page of the pagination
  */
  /* currentPage: number; */
  /**
   * Determines the total number of records
  */
  totalRecords?: number;
  /**
   * Determines the total page of the pagination
  */
  totalPages: number;
  /**
   * Label for current page over total pages in type *responsive*
  */
  pageInfoLabel?: string;
  /**
   *Page change event of the pagination
  */
  onPageChange: (page: number) => void;

  /**
   *Determines the total items Per Page
  */
   onItemsPerPageChange?: (items: number) => void;    
   /**
   *Determines the total items Per Page
  */
  /* itemsPerPage: number; */
  /**
   * Determines the variant of the pagination: circle, square.
  */
  variant?: "icon" | "label" | "label-and-icon";
 
  /**
  * Determines the type of the pagination.
  */
  type: "table" | "responsive" | "slider" ;
  /**
   * Determines the shape of the pagination: circle, square.
  */
  shape?: "circle" | "square" ;

  /**
   * Determines the colour of the pagination: primary, secondary, tertiary.
  */
  colour?: "primary" | "secondary" | "tertiary";

   /**
   * Determines the outline or non outline of the pagination
  */
   outline?: "outline" | "none" ;

   /**
    * Determines whether to show rows per page dropdown or not
    */
   showRowsPerPage?: boolean;
   /**
   * Optional width for the "Go To Page" TextField
   * Example: "150px", "10rem"
   */
  goToPageInputWidth?: string;

  /**
 * Controls the alignment of pagination buttons: left or right
 */
  paginationButtonsPosition?: "left" | "right";
}

const Pagination: React.FC<PaginationProps> = ({
  id,
  // currentPage=1,
  totalRecords=0,
  totalPages=1,
  pageInfoLabel = "of",
  onPageChange = () => {},
  onItemsPerPageChange,
  // itemsPerPage=10,
  variant="icon",
  shape,
  colour,
  outline,
  type="table",
  showRowsPerPage = true,
  goToPageInputWidth,
  paginationButtonsPosition = "right"
}) => {
  
// Generate page buttons dynamically based on totalPages
let paginationClassName = [
  "mpa-pagination ",
  `${shape || "circle"}`, 
  `${colour || "primary"}`, 
  `${outline || "none"}`
].filter(Boolean).join(" ");

let paginationButtonClassName = [
  "mpa-pagination ",
  `${variant || "icon"}`,
  `${shape || "circle"}`, 
  `${colour || "primary"}`, 
  `${outline || "none"}`
].filter(Boolean).join(" ");


const [showDropdown, setShowDropdown] = useState(false);
const [selectedValue, setSelectedValue] = useState(10);
const [currentPageValue, setCurrentPageValue] = useState(1);

// Function to show or hide dropdown
const showDropDown = () => {
  setShowDropdown(!showDropdown); // Toggle dropdown visibility
};

// Function to handle item selection
const handleSelect = (value: any) => {
  setSelectedValue(value); // Update the selected value
  setShowDropdown(false); // Hide the dropdown after selection
  if(onItemsPerPageChange){
    onItemsPerPageChange(value);
  }
};


const [pageInput, setPageInput] = useState("");

// Handler to update pageInput
const handlePageInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
  const newValue = e.target.value;
  setPageInput(newValue);

  if (newValue.trim() !== "" && !isNaN(Number(newValue))) {
    const pageNumber = Number(newValue);
    if (pageNumber >= 1 && pageNumber <= totalPages) {
      handleGoToPage(pageNumber);
    } else {
      alert(`Please enter a valid page number between 1 and ${totalPages}.`);
      setPageInput("");
    }
  }
};

const handleGoToPage = (pageInput: number) => {
  const pageNumber = Number(pageInput);
  if (pageNumber >= 1 && pageNumber <= totalPages) {
    setCurrentPageValue(pageNumber);
    onPageChange(pageNumber);
  } else {
    // Optionally show an alert or error message for invalid input
    alert(`Please enter a valid page number between 1 and ${totalPages}.`);
  }
};


const onNextPage = () => {
  if (currentPageValue < totalPages) {
    setCurrentPageValue(currentPageValue + 1);
    onPageChange(currentPageValue + 1); 
  }
};

const onPreviousPage = () => {
  if (currentPageValue > 1) {
    setCurrentPageValue(currentPageValue - 1);
    onPageChange(currentPageValue - 1); 
  }
};


const rowsPerPage = [10, 20, 50, 100];

const getPageRange = () => {
  const range: (number | string)[] = [];

  if (totalPages <= 7) {
    // Show all pages if total is small
    for (let i = 1; i <= totalPages; i++) {
      range.push(i);
    }
  } else {
    if (currentPageValue <= 4) {
      range.push(1, 2, 3, 4, 5, '...', totalPages);
    } else if (currentPageValue >= totalPages - 3) {
      range.push(1, '...', totalPages - 4, totalPages - 3, totalPages - 2, totalPages - 1, totalPages);
    } else {
      range.push(1, '...', currentPageValue - 1, currentPageValue, currentPageValue + 1, '...', totalPages);
    }
  }
  return range;
};
const pageRange = getPageRange();

// Generate the page buttons based on the PageRange
const pageButtons = pageRange.map((page, index) => {
  if (page === '...') {
    return (
      <span
        key={`ellipsis-${index}`}
        className={`${paginationClassName} ellipsis`}
      >
      <span>...</span>
      </span>
    );
  } else {
    return (
      <span
          key={`page-${page}`}
          onClick={() => {
            setCurrentPageValue(page as number);
            onPageChange(page as number);
          }}
          className={`${paginationClassName} ${currentPageValue === page ? 'selected' : ''} `}
      >
          {page}
      </span>
    );
  }
});

  return (
    <div id={id} className={`pagination-controls`}>
        {/* Condition for type being 'table' */}
        {type === 'table' && (        
            <>
             <div className="rows-per-page-dropdown">              
                {showRowsPerPage && (
                  <>
                  <span style={{width:"100px"}} >Rows Per Page </span>
                  <div className="dropdown">
                        <span onClick={showDropDown} className="dropdown-toggle">
                          <span>{selectedValue}</span>                     
                          {<MpaIcon iconName={"ChevronDown"}/>}
                        </span> 
                          
                        {showDropdown && (
                        <div className="dropdown-menu" aria-labelledby="dropdownMenuLink">
                          {rowsPerPage.map((value) => (
                            <span  key={value} className="dropdown-item" onClick={() => handleSelect(value)}>
                              {value}
                            </span>   
                            
                          ))}
                        </div>
                        )}
                  </div>
                  
                  <div>
                      {`1–${selectedValue} of ${totalRecords} items`}
                  </div>

                </>
                )}
            </div>
            
            <div className={`pagination-buttons-wrapper ${paginationButtonsPosition === "left" ? "left" : ''}`}>
                 <div className='pagination-buttons'>         
                  <span
                    onClick={onPreviousPage}
                    className={`${paginationButtonClassName} ${currentPageValue === 1 ? 'disabled' : ''} prev`}
                  >
                    {
                      variant === "icon" ? <MpaIcon iconName={"ChevronLeft"}/> :
                      variant === "label" ? "Previous":
                      variant === "label-and-icon" ? <><MpaIcon iconName={"ChevronLeft"}/>Previous</> : null
                    }
                  </span>

                  {/* Page Numbers */}
                  {pageButtons}
                    <span
                      onClick={onNextPage}
                      className={`${paginationButtonClassName} ${currentPageValue === totalPages ? 'disabled' : ''} next`}
                    >
                    {
                        variant === "icon" ? <MpaIcon iconName={"ChevronRight"}/> :
                        variant === "label" ? "Next":
                        variant === "label-and-icon" ? <> Next <MpaIcon iconName={"ChevronRight"}/> </> : null                   
                    }
                  </span>
                </div>

                <div className="page-navigation">
                  <span>Go To Page:</span>
                    <TextField id={"textFieldId"} 
                      type="number"
                      value={currentPageValue.toString()}
                      width={goToPageInputWidth}
                      // label="Go To Page:"
                      onChange={handlePageInputChange}
                    />
                </div>

            </div>
            </>
          )}

          {/* Condition for type 'responsive' */}
          {type === 'responsive' && (
          <div className="responsive">           
                <span
                    onClick={onPreviousPage}
                    className={`${paginationButtonClassName} ${currentPageValue === 1 ? 'disabled' : ''} prev`}
                  >
                   {
                      variant === "icon" ?  <MpaIcon iconName={"ChevronLeft"}/> :
                      variant === "label" ? "Previous":
                      variant === "label-and-icon" ? <><MpaIcon iconName={"ChevronLeft"}/>Previous</> : null
                  }
                </span>


              {/* Current page / Total pages */}
              <span className="page-info">
                {currentPageValue} {pageInfoLabel} {totalPages}
              </span>

                <span
                    onClick={onNextPage}
                    className={`${paginationButtonClassName} ${currentPageValue === totalPages ? 'disabled' : ''} next`}
                  >
                   {
                      variant === "icon" ?  <MpaIcon iconName={"ChevronRight"}/> :
                      variant === "label" ? "Next":
                      variant === "label-and-icon" ? <>Next <MpaIcon iconName={"ChevronRight"}/></> : null
                  }
                </span>

          </div>
        )}
          
          {/* Condition for type being 'slider' */}
          {type === 'slider' && 
            <div className="slider-pagination">
            {/* Render the page buttons as dots */}
            {Array.from({ length: totalPages }, (_, index) => index + 1).map((page) => (
              <div
                key={page}
                onClick={() => {
                  setCurrentPageValue(Number(page)); // Update the current page value
                  onPageChange(Number(page)); // Notify the parent component of the page change
                }}
                className={`pagination-dot ${currentPageValue === page ? 'selected' : ''}`}
              />
            ))}
          </div>
          }
    </div>
  );
};

export default Pagination;
